				batchId,
				mappings: parseMappings(String(formData.get('mappings') || '[]'))
			});
			throw redirect(303, batchRedirect(batchId, 'staged'));
		} catch (error) {
			if (isRedirect(error)) throw error;
			return fail(400, {
				action: 'accept-and-stage',
				batchId,
				error: adminBatchWorkflowError(error)
			});
		}
	},

